expected_claims AS (SELECT c FROM data,jsonb_array_elements(d->'claims') c),
expected_anchors AS (SELECT c FROM data,jsonb_array_elements(d->'anchors') c),
expected_links AS (SELECT c FROM data,jsonb_array_elements(d->'links') c)
SELECT 'target_lifecycle_preserved' check_name,(SELECT count(*)=3 AND bool_and(status='published') FROM software_discovery.products WHERE slug IN ('pdf-xchange-editor','pdf24-creator','pdfgear')) passed
UNION ALL SELECT 'nine_exact_reviewed_attributes',(SELECT count(*)=9 AND bool_and(EXISTS(SELECT 1 FROM software_discovery.product_attributes a JOIN software_discovery.products p ON p.id=a.product_id JOIN software_discovery.attributes t ON t.id=a.attribute_id WHERE p.slug=c->>'product' AND t.slug=c->>'attribute' AND coalesce(to_jsonb(a.value_boolean),to_jsonb(a.value_text),to_jsonb(a.value_number),to_jsonb(a.value_enum))=c->'value' AND a.verification_status='verified' AND a.confidence=(c->>'confidence')::numeric AND a.last_verified_at=(c->>'date')::timestamptz)) FROM expected_claims)
UNION ALL SELECT 'three_exact_bounded_anchors',(SELECT count(*)=3 AND bool_and(EXISTS(SELECT 1 FROM software_discovery.product_anchors a JOIN software_discovery.products p ON p.id=a.product_id JOIN software_discovery.anchors t ON t.id=a.anchor_id WHERE p.slug=c->>'product' AND t.slug='adobe-pdf' AND a.relationship_type='alternative' AND a.relationship_scope=c->>'scope' AND a.scope_description=c->>'scopeDescription' AND a.verification_status='verified' AND a.confidence=.85 AND a.last_verified_at=(c->>'lastVerifiedAt')::timestamptz)) FROM expected_anchors)
UNION ALL SELECT 'reviewed_and_historical_evidence_retained',(SELECT bool_and(CASE WHEN c->>'kind'='attributes' THEN EXISTS(SELECT 1 FROM software_discovery.product_attribute_evidence l JOIN software_discovery.products p ON p.id=l.product_id JOIN software_discovery.attributes a ON a.id=l.attribute_id JOIN software_discovery.claim_evidence e ON e.id=l.claim_evidence_id JOIN software_discovery.evidence_sources s ON s.id=e.evidence_source_id WHERE p.slug=c->>'product' AND a.slug=c->>'slug' AND s.seed_key=c->>'source') ELSE EXISTS(SELECT 1 FROM software_discovery.product_anchor_evidence l JOIN software_discovery.products p ON p.id=l.product_id JOIN software_discovery.anchors a ON a.id=l.anchor_id JOIN software_discovery.claim_evidence e ON e.id=l.claim_evidence_id JOIN software_discovery.evidence_sources s ON s.id=e.evidence_source_id WHERE p.slug=c->>'product' AND a.slug=c->>'slug' AND l.relationship_type='alternative' AND s.seed_key=c->>'source') END) FROM expected_links)
UNION ALL SELECT 'pdf_route_published_and_approved',EXISTS(SELECT 1 FROM software_discovery.escape_routes WHERE slug='pdf-editors-without-a-subscription' AND status='published' AND editorially_approved)
UNION ALL SELECT 'fifteen_products_six_routes',(SELECT count(*)=15 FROM software_discovery.products WHERE status='published') AND (SELECT count(*)=6 FROM software_discovery.escape_routes WHERE status='published' AND editorially_approved)
UNION ALL SELECT 'three_products_visible_in_public_rpc',software_discovery.product_discovery_page('pdf-xchange-editor') IS NOT NULL AND software_discovery.product_discovery_page('pdf24-creator') IS NOT NULL AND software_discovery.product_discovery_page('pdfgear') IS NOT NULL
UNION ALL SELECT 'pdf_route_exact_three_members',(SELECT count(*)=3 AND count(DISTINCT p.slug)=3 AND bool_and(p.slug IN ('pdf-xchange-editor','pdf24-creator','pdfgear')) FROM software_discovery.escape_route_products m JOIN software_discovery.products p ON p.id=m.product_id JOIN software_discovery.escape_routes r ON r.id=m.escape_route_id WHERE r.slug='pdf-editors-without-a-subscription')
UNION ALL SELECT 'prior_offline_anchors_preserved',(SELECT count(*)=3 AND bool_and(c.relationship_scope='personal-offline-note-object-organization' AND c.verification_status='verified') FROM software_discovery.product_anchors c JOIN software_discovery.products p ON p.id=c.product_id JOIN software_discovery.anchors a ON a.id=c.anchor_id WHERE p.slug IN ('affine','appflowy','anytype') AND a.slug='notion' AND c.relationship_type='alternative')
UNION ALL SELECT 'anon_private_evidence_boundary',has_function_privilege('anon','software_discovery.product_discovery_page(text)','EXECUTE') AND NOT has_table_privilege('anon','software_discovery.claim_evidence','SELECT')
UNION ALL SELECT 'public_pdf_scope_and_sources',(SELECT count(*)=3 AND bool_and(EXISTS(SELECT 1 FROM jsonb_array_elements(software_discovery.product_discovery_page(p.slug)->'anchors') a WHERE a->>'slug'='adobe-pdf' AND a->>'scope'='windows-personal-pdf-page-organization' AND a->>'verificationStatus'='verified' AND length(a->>'description')>0 AND jsonb_array_length(a->'sources')>0)) FROM software_discovery.products p WHERE slug IN ('pdf-xchange-editor','pdf24-creator','pdfgear'));
